/* Declared with gint's own font_t so the compiler lays the bitfield
 * byte, the pointers and the trailing metrics out exactly the way
 * gint's renderer reads them. */
static font_t const ss3_font = {
    "Source Sans 3",
    0, 0, 0, 0,              /* bold, italic, serif, mono */
    0,                       /* prop: fixed-width cell */
    14,                      /* line_height */
    14,                      /* data_height */
    57,                      /* block_count */
    293,                      /* glyph_count */
    0,                       /* char_spacing: advance == 9 px */
    (void *)ss3_blocks,
    (void *)ss3_data,
    { .width = 9, .storage_size = 4 }
};

font_t const *ss3_font_get(void) { return &ss3_font; }
